const TIMES = [0.388,0.427,0.465,0.504,0.581,0.619,0.658,0.735,0.773,0.812,0.85,0.888,0.927,0.965,1.042,1.081,1.119,1.158,1.196,1.273,1.312,1.388,1.427,1.465,1.542,1.581,1.619,1.658,1.696];
for (const t of TIMES) {
  const n = kit.noise('white', 0.04), bp = ctx.createBiquadFilter(); bp.type = 'bandpass'; bp.frequency.value = 2600 + kit.random() * 1800; bp.Q.value = 1.4;
  const g = ctx.createGain(); g.gain.setValueAtTime(0, t); g.gain.linearRampToValueAtTime(0.5 + kit.random() * 0.3, t + 0.001); g.gain.setTargetAtTime(0, t + 0.002, 0.008);
  const o = ctx.createOscillator(); o.frequency.value = 1500 + kit.random() * 600;
  const go = ctx.createGain(); go.gain.setValueAtTime(0, t); go.gain.linearRampToValueAtTime(0.12, t + 0.001); go.gain.setTargetAtTime(0, t + 0.002, 0.01);
  n.connect(bp).connect(g).connect(ctx.destination); o.connect(go).connect(ctx.destination);
  n.start(t); o.start(t); o.stop(t + 0.06);
}
